let score = 0;
let lives = 1;
let gameState = 'PLAYING';
let rng = null;

// Game constants
const TILE_SIZE = 20;
const GRAVITY = 0.4;
const JUMP_V = -7.5;
const MAX_SPEED = 4;
const ACCEL = 1.0;
const FRICTION = 0.7;

// Entities
