function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 1;
  gameState = 'PLAYING';

  solidBlocks = [];
  spikes = [];
  coins = [];
  prevJumpPressed = false;

  let grid = Array(20).fill().map(() => Array(20).fill(false));

